import{_ as a,o as t,c as i,ag as s}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Encapsulation — the details","description":"","frontmatter":{},"headers":[],"relativePath":"design_patterns/foundations/oop_pillars/encapsulation/Encapsulation.md","filePath":"design_patterns/foundations/oop_pillars/encapsulation/Encapsulation.md"}'),n={name:"design_patterns/foundations/oop_pillars/encapsulation/Encapsulation.md"};function o(l,e,r,c,d,p){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="encapsulation-—-the-details" tabindex="-1">Encapsulation — the details <a class="header-anchor" href="#encapsulation-—-the-details" aria-label="Permalink to &quot;Encapsulation — the details&quot;">​</a></h1><blockquote><p>First of the four OOP pillars. Builds on access modifiers, paired with Abstraction.</p></blockquote><hr><h2 id="beyond-private-fields-public-methods" tabindex="-1">Beyond &quot;private fields, public methods&quot; <a class="header-anchor" href="#beyond-private-fields-public-methods" aria-label="Permalink to &quot;Beyond &quot;private fields, public methods&quot;&quot;">​</a></h2><p>Encapsulation is <em>information hiding</em> — a deliberate decision about what to expose and what to protect. Access modifiers are the tool; the principle is bigger.</p><p><strong>Three layers</strong> (each demonstrated by a class in this folder):</p><ol><li><strong>Field-level</strong> — <code>private</code> fields, accessed only through methods. Any validation or invariant enforcement lives in those methods, not scattered across callers. See <code>FieldLevel.java</code>.</li><li><strong>Package-level</strong> — no access modifier (package-private) means visible within the package, hidden from outside. Used in the factory packages: <code>AndroidDeveloper</code> is package-private so external code cannot <code>new AndroidDeveloper()</code> — it must go through <code>AndroidHiringProcess</code>. See <code>PackageLevel.java</code> and the cross-package counter-demo in <code>other/CrossPackageAccessRun.java</code>.</li><li><strong>Construction-level</strong> — <code>final</code> fields + a validating constructor and no setter (or private constructors + factory methods). The class controls <em>how</em> it&#39;s created and stays valid for its whole lifetime. This is also what <code>BillPughSingleton</code>, <code>JobOffer.Builder</code>, and <code>Temperature.celsius()</code> all exploit. See <code>ConstructorLevel.java</code>.</li></ol><p><code>PackageLevel</code> is deliberately mixed: a <code>public</code> field/method (visible everywhere) sits next to a package-private field/method (visible only to same-package code). The cross-package runner reads the <code>public</code> ones successfully and keeps the package-private accesses as commented-out lines — uncomment one and <code>mvn -q compile</code> rejects it. That contrast is the clearest way to feel where the package boundary actually sits.</p><hr><h2 id="immutability-as-the-strongest-encapsulation" tabindex="-1">Immutability as the strongest encapsulation <a class="header-anchor" href="#immutability-as-the-strongest-encapsulation" aria-label="Permalink to &quot;Immutability as the strongest encapsulation&quot;">​</a></h2><p><code>final</code> fields + no setters = nothing outside the object can corrupt its state after construction. Callers can read; they can never write.</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// No setter, final field — once set in the constructor, salary is sealed</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> final</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> salary;</span></span></code></pre></div><p>This is what the EJ Builder pattern achieves for <code>JobOffer</code>: the object is fully validated in <code>build()</code> and then frozen. Any future caller who holds the <code>JobOffer</code> reference cannot put it into an invalid state.</p><hr><h2 id="encapsulation-violations-to-watch-for" tabindex="-1">Encapsulation violations to watch for <a class="header-anchor" href="#encapsulation-violations-to-watch-for" aria-label="Permalink to &quot;Encapsulation violations to watch for&quot;">​</a></h2><p><strong>Returning a mutable field reference directly:</strong></p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Bad — caller can mutate internal state</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> List</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Point</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getPoints</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> points; }</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Better — caller gets a read-only view</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> List</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Point</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getPoints</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Collections.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">unmodifiableList</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(points); }</span></span></code></pre></div><p><code>ShapeShallow</code> does this intentionally so the shallow-copy trap is visible. In production code, this would be a bug.</p><p><strong>Public fields:</strong></p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">public</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> salary; </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// any caller can set it to -1 with no validation</span></span></code></pre></div><p><strong>Setter on an &quot;immutable&quot; class:</strong> adding <code>setSalary(int)</code> to <code>JobOffer</code> after building it via the Builder defeats the entire point — the object is no longer immutable.</p><hr><h2 id="encapsulation-and-testability" tabindex="-1">Encapsulation and testability <a class="header-anchor" href="#encapsulation-and-testability" aria-label="Permalink to &quot;Encapsulation and testability&quot;">​</a></h2><p>A well-encapsulated class is easy to test in isolation because:</p><ul><li>Its dependencies arrive via the constructor (or a seam) rather than being hardcoded inside.</li><li>Its state is changed only through its own methods, so the test can set up known state and trust it stays that way.</li></ul><p>A class that <code>new</code>s its own dependencies internally (hardcoded <code>new EmailService()</code>) is poorly encapsulated at the dependency boundary — there&#39;s no seam to inject a test double.</p><hr><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. Name three encapsulation violations.</strong> A. Returning a mutable field reference; public fields; providing a setter on a class meant to be immutable.</p><p><strong>Q. Same package vs different package — what changes?</strong> A. Same package sees both <code>public</code> and package-private members. A different package only sees <code>public</code>; package-private members don&#39;t compile.</p><p><strong>Q. Two practical fixes for &quot;returning a mutable field&quot;?</strong> A. Return <code>Collections.unmodifiableList(list)</code> (read-only view) or <code>List.copyOf(list)</code> (defensive copy).</p><p><strong>Q. Why is constructor-level encapsulation stronger than a validating setter?</strong> A. The object is born valid (constructor checks the invariant) and a <code>final</code> field can never become invalid afterward — there&#39;s no setter to misuse later.</p><hr><h2 id="related-topics" tabindex="-1">Related topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related topics&quot;">​</a></h2><ul><li><strong>Abstraction</strong> — works alongside encapsulation. Abstraction hides <em>complexity</em>; encapsulation hides <em>state</em>.</li><li><strong>Access Modifiers Deep Dive</strong> — the precise Java mechanics behind field-level and package-level encapsulation.</li><li><strong>Java Collections</strong> — <code>Collections.unmodifiableList(...)</code> and <code>List.copyOf(...)</code> are the practical tools for fixing the &quot;returning a mutable field&quot; violation.</li></ul>`,35)])])}const k=a(n,[["render",o]]);export{u as __pageData,k as default};
